function typeOf(value) {
  if (typeof value === 'number') return Number.isInteger(value) ? 'Long' : 'Double';
  if (typeof value === 'boolean') return 'Bool';
  return 'String';
}

// FlatGeobuf writer: the column schema.
export function columnsOf(layer) {
  const first = layer.features[0].properties;
  return Object.entries(first).map(([name, value]) => ({ name, type: typeOf(value) }));
}
